    function __ESBMC_assume(bool) internal pure {}

    function run(address _target, uint _value, bytes calldata _data) public payable {
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        bool reverted;
        c.sendMoney(_target, _value, _data); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        bool insufficient = _value > balanceBefore;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(c).balance;

        assert(!insufficient || (reverted && balanceAfter == balanceBefore && depositsAfter == depositsBefore));
    }

    receive() external payable {}
}

