pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address _target, uint256 _value, bytes memory _data) internal {
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.sendMoney(_target, _value, _data) { reverted = false; } catch { reverted = true; }
        bool insufficient = _value > balanceBefore;
        uint256 depositsAfter;
        try c.depositsCount() returns (uint256 __r) { depositsAfter = __r; } catch { return; }
        uint balanceAfter = address(c).balance;
        assertTrue(!insufficient || (reverted && balanceAfter == balanceBefore && depositsAfter == depositsBefore));
    }

